INSERT INTO hashtag (hashtag_idx, tags) SELECT seq_hashtag.nextval, tags FROM (
SELECT #{tag} AS tags FROM DUAL
)

mapper.select:
select U.login_id from users U
join coach C on U.user_idx = C.user_idx
where C.mail = #{email}

select U.login_id from users U
join company C on U.user_idx = C.user_idx
where C.email = #{email}

mapper.delete:
DELETE FROM likes_user
WHERE liker_idx=#{login_idx}
AND liked_user_idx=#{target_idx}

mapper.select:
SELECT * FROM ( SELECT c.coach_idx, c.user_idx, c.birth_date, c.nickname, c.phone, c.mail, c.intro, c.photo, c.video, c.point_score, c.token_balance, c.kakao_key,
/* 등급 */ r.rank_name AS rank_name,
/* 최근 7일 찜 */ NVL(l.like_count, 0) AS like_count,
/* 누적 리뷰수 */ NVL(rv.review_count, 0) AS review_count,
/* 평균 평점 */ NVL(rv.avg_rating, 0) AS rating
FROM coach c
/* ⭐ rank 범위 조인 */ LEFT JOIN rank r ON c.point_score >= r.min_score AND (r.max_score IS NULL OR c.point_score < r.max_score)
/* ⭐ 최근 7일 찜수 */ LEFT JOIN ( SELECT liked_user_idx AS user_idx, COUNT(*) AS like_count FROM likes_user WHERE created_at >= SYSDATE - 7 GROUP BY liked_user_idx ) l ON l.user_idx = c.user_idx
/* ⭐ 리뷰 통계 */ LEFT JOIN ( SELECT reviewee_idx AS user_idx, COUNT(*) AS review_count, ROUND(AVG(rating), 1) AS avg_rating FROM review_coach GROUP BY reviewee_idx ) rv ON rv.user_idx = c.user_idx
/* ⭐ 인기 기준 = 찜 */ ORDER BY NVL(l.like_count, 0) DESC, c.coach_idx DESC ) WHERE ROWNUM <= 5

select * from schedule
where agreement_idx = #{agreement_idx}
order by start_date asc
